// 道具刷光：斜向光带扫过，只作用在实体（alpha）上
uniform sampler2D u_sprite;  // 道具图（带透明通道）
uniform float u_width;       // @range 0.02 0.5 @step 0.01 @default 0.06 @label 光带宽度
uniform float u_angle;       // @range -1 1 @step 0.01 @default -0.42 @label 扫光角度
uniform vec3  u_color;       // @color @label 光颜色
uniform float u_gain;        // @range 0 4 @step 0.01 @default 0.7 @label 亮度
uniform float u_trail;       // @range 0 1 @step 0.01 @default 0.12 @label 余晖

void main() {
  vec4 s = texture(u_sprite, vUv);

  // 沿角度方向做投影，光带在该轴上移动
  float ca = cos(u_angle), sa = sin(u_angle);
  float d = vUv.x * ca + vUv.y * sa;

  // 头尾各留一点余量，保证光带完整扫过
  float head = mix(-0.25, 1.25, sl_easeInOut(u_t01));

  // 主光带 + 更宽的一层余晖（pow 负数底未定义，平方写成 q*q）
  float q = (d - head) / u_width;
  float band = exp(-q * q);
  float qh = (d - head) / (u_width * 2.6);
  float halo = exp(-qh * qh) * u_trail;

  // 只在实体上（alpha 当遮罩），边缘用 alpha 软过渡
  float mask = smoothstep(0.0, 0.85, s.a);
  vec3 shine = u_color * (band + halo) * u_gain * mask;

  vec3 c = s.rgb + shine;
  fragColor = vec4(c, s.a);
}

// 描边：先把 alpha 二值化，再在「形状」上做 Sobel，得到一圈干净的发光线
uniform sampler2D u_sprite;  // 道具图（靠 alpha 找边）
uniform float u_thickness;   // @range 1 6 @step 0.1 @default 2.0 @label 描边粗细
uniform vec3  u_color;       // @color @label 描边颜色
uniform float u_gain;        // @range 0 4 @step 0.01 @default 2.4 @label 亮度
uniform float u_freq;        // @range 0 6 @step 0.05 @default 1.4 @label 呼吸次数
uniform float u_soft;        // @range 0.02 0.5 @step 0.01 @default 0.12 @label 边缘柔化

// 把 alpha 阈值化成形状：直接用原始 alpha（软边）会让 Sobel 输出一条很宽的带子
float shape(vec2 uv) {
  return smoothstep(0.5 - u_soft, 0.5 + u_soft, texture(u_sprite, uv).a);
}

void main() {
  vec2 e = u_texel * u_thickness;

  float l  = shape(vUv - vec2(e.x, 0.0));
  float r  = shape(vUv + vec2(e.x, 0.0));
  float b  = shape(vUv - vec2(0.0, e.y));
  float t  = shape(vUv + vec2(0.0, e.y));
  float tl = shape(vUv - e);
  float tr = shape(vUv + vec2(e.x, -e.y));
  float bl = shape(vUv + vec2(-e.x, e.y));
  float br = shape(vUv + e);

  // Sobel：形状的梯度就是轮廓
  float gx = (tl + 2.0 * l + bl) - (tr + 2.0 * r + br);
  float gy = (tl + 2.0 * t + tr) - (bl + 2.0 * b + br);
  float edge = clamp(sqrt(gx * gx + gy * gy), 0.0, 1.0);

  // 呼吸：亮度做正弦起伏
  float breath = 0.45 + 0.55 * (0.5 + 0.5 * sin(u_time * u_freq * TAU));

  vec3 col = u_color * edge * breath;

  // 颜色保持色相，亮度交给 alpha，叠在背景上不会糊成一片白
  float m = max(col.r, max(col.g, col.b));
  fragColor = vec4(col / max(m, 1e-3), clamp(m * u_gain, 0.0, 1.0));
}

// 柔光：对上一 Pass 做一次 9 tap 高斯，用来把描边晕开
uniform sampler2D u_src;   // 上一 Pass 的输出
uniform float u_radius;    // @range 0.5 8 @step 0.1 @default 2.4 @label 扩散半径
uniform float u_gain;      // @range 0 3 @step 0.01 @default 1.1 @label 增益

void main() {
  vec2 e = u_texel * u_radius;
  vec4 sum = texture(u_src, vUv) * 0.227;
  sum += (texture(u_src, vUv + vec2(e.x, 0.0)) + texture(u_src, vUv - vec2(e.x, 0.0))) * 0.158;
  sum += (texture(u_src, vUv + vec2(0.0, e.y)) + texture(u_src, vUv - vec2(0.0, e.y))) * 0.158;
  sum += (texture(u_src, vUv + e) + texture(u_src, vUv - e)) * 0.05;
  sum += (texture(u_src, vUv + vec2(e.x, -e.y)) + texture(u_src, vUv + vec2(-e.x, e.y))) * 0.05;

  // 保留原图一部分，避免糊成一团
  vec4 base = texture(u_src, vUv);
  vec4 outCol = mix(base, sum, 0.75) * u_gain;
  fragColor = vec4(outCol.rgb, clamp(outCol.a, 0.0, 1.0));
}

// 刀光 · 弧形横扫
// 一次性效果：u_t01 从 0 走到 1，刀光沿弧线从左上扫到右下。
uniform float u_intensity; // @range 0 3 @step 0.01 @default 1.6 @label 强度
uniform float u_spread;    // @range 0.5 3 @step 0.01 @default 1.0 @label 拖尾长度
uniform vec3  u_color;     // @color @label 刀光颜色

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  float r = length(p);
  float ang = atan(p.y, p.x);

  // 扫过角度：-2.4 → 2.4；起手快、收尾慢
  float t = sl_easeOut(u_t01);
  float head = mix(-2.4, 2.4, t);

  // 头部亮线 + 身后拖尾（角度差越大越暗）
  float da = head - ang;
  float lead = exp(-abs(da) * 26.0);
  float trail = exp(-max(da, 0.0) * 2.0 / u_spread);

  // 弧带：半径 0.62 附近的一条带子
  // 注意：pow(x, 2.0) 在 x<0 时 GLSL 未定义，平方一律写成 q*q
  float q = (r - 0.62) / 0.04;
  float band = exp(-q * q);

  // 只画「已经扫过」的角度范围，起点留一段软过渡
  float swept = smoothstep(-3.15, -2.65, ang) * smoothstep(head + 0.02, head - 0.08, ang);

  float glow = band * swept * (trail * 0.45 + lead * 1.35);

  // 起手时中心的一点光：只在 t01 的开头出现，且随距离快速衰减
  float startFlash = exp(-r * 9.0) * smoothstep(0.3, 0.0, u_t01) * 0.8;

  vec3 col = u_color * (glow + startFlash);

  // 颜色保持色相，亮度交给 alpha：叠在背景上不会因为过曝糊成一片白
  float m = max(col.r, max(col.g, col.b));
  fragColor = vec4(col / max(m, 1e-3), clamp(m * u_intensity, 0.0, 1.0));
}

// 水流扰动：噪声推 UV + 高光
uniform sampler2D u_tex;   // 场景（会被扭曲的那张图）
uniform sampler2D u_noise; // 噪声图
uniform float u_strength;  // @range 0 0.12 @step 0.001 @default 0.028 @label 扰动强度
uniform float u_speed;     // @range 0 3 @step 0.01 @default 0.45 @label 流速
uniform float u_scale;     // @range 0.5 8 @step 0.1 @default 2.2 @label 波纹密度
uniform float u_caustic;   // @range 0 3 @step 0.01 @default 0.9 @label 水面高光

void main() {
  vec2 uv = vUv;
  float t = u_time * u_speed;

  // 两层不同速度、不同尺度的噪声滚过去，避免看出平铺
  float n1 = texture(u_noise, uv * u_scale + vec2(t * 0.07, t * 0.03)).r;
  float n2 = texture(u_noise, uv * u_scale * 1.7 - vec2(t * 0.05, t * 0.09)).r;
  vec2 off = vec2(n1, n2) - 0.5;

  // 用噪声当位移场；采样点稍微偏一点就能看出水的折射感
  vec3 c = texture(u_tex, uv + off * u_strength).rgb;

  // 高光：两个噪声相乘取亮部，模拟水面被照亮的地方
  float caustic = pow(clamp(n1 * n2 * 1.9, 0.0, 1.0), 3.0) * u_caustic;
  c += vec3(0.45, 0.7, 1.0) * caustic * 0.5;

  // 极轻的暗角，让画面聚焦
  float vig = 1.0 - 0.25 * pow(length(vUv - 0.5) * 1.8, 2.0);
  fragColor = vec4(c * vig, 1.0);
}
